/* Offline cache (generated by tools/build.ps1). Every file of the app is stored on the phone; the list page and
   library.json are checked online first so new pages show up, the pages themselves open from the phone. */
const VERSION = 'pf-5a06f37ff322';
const FILES = [
  './',
  './index.html',
  './library.json',
  './manifest.webmanifest',
  './icon-180.png',
  './icon-192.png',
  './icon-512.png',
  './t/01.html',
  './t/02.html',
  './t/03.html',
  './t/04.html',
  './t/05.html',
  './t/06.html',
  './t/07.html',
  './t/08.html',
  './t/09.html',
  './t/10.html',
  './t/11.html',
  './t/12.html',
  './t/13.html',
  './t/14.html',
  './t/15.html',
  './t/21.html',
  './t/16.html',
  './t/17.html',
  './t/18.html',
  './t/19.html',
  './t/20.html',
  './t/22.html',
  './t/23.html',
  './t/24.html',
  './k/01.html',
  './k/02.html',
  './k/03.html',
  './c/01.html'
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION)
    .then(c => c.addAll(FILES.map(u => new Request(u, { cache: 'reload' }))))
    .then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

function save(req, res) {
  if (res && (res.ok || res.type === 'opaque')) {
    const copy = res.clone();
    caches.open(VERSION).then(c => c.put(req, copy));
  }
  return res;
}

/* online answer when it comes within 4 s, otherwise the stored copy */
function networkFirst(req, fallback) {
  const net = fetch(req).then(res => save(req, res));
  const stored = caches.match(req, { ignoreSearch: true }).then(hit => hit || (fallback && caches.match(fallback)));
  return new Promise(resolve => {
    let done = false;
    const give = r => { if (!done && r) { done = true; resolve(r); } };
    const timer = setTimeout(() => stored.then(give), 4000);
    net.then(r => { clearTimeout(timer); give(r); })
      .catch(() => { clearTimeout(timer); stored.then(r => r ? give(r) : give(Response.error())); });
  });
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const isFont = url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com';
  if (url.origin !== location.origin && !isFont) return;
  if (req.mode === 'navigate') { e.respondWith(networkFirst(req, './index.html')); return; }
  if (url.pathname.endsWith('/library.json')) { e.respondWith(networkFirst(req)); return; }
  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req).then(res => save(req, res)))
  );
});
